/* =============================================================================
   build-css-bundle.mjs — concatenate the stylesheets into css/crnl.css
   =============================================================================
   crnl-loader.js is a render-blocking <script>: it has to download and execute
   before the first stylesheet request even leaves, and then injects 22 more
   render-blocking <link>s. That is the one real cost of shipping a file per
   concern — not bytes, but a round trip and a request per sheet.

   So the split stays the authoring format and the bundle becomes the delivery
   format: crnl-loader.js links this file when it is running against a deployed
   site, and the individual sheets when it is local, which keeps `edit CSS →
   reload` working with no build step in between.

   Output is gitignored. A committed copy would go stale the moment any
   stylesheet changed.

   Run:  npm run build:css-bundle
   Out:  css/crnl.css
   ============================================================================= */

import { readFileSync, writeFileSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { gzipSync } from 'node:zlib'
import { readLoadOrder, readLayers } from './lib/load-order.mjs'

const CSS = join(dirname(fileURLToPath(import.meta.url)), '..', 'css')
const OUT = join(CSS, 'crnl.css')

const sheets = readLoadOrder()
const { order, layerFor } = readLayers()

/* Relative url()s resolve against the stylesheet they appear in. Every sheet
   here sits in css/ and so does the bundle, so `url('../images/…')` and
   `url('../fonts/…')` keep resolving to the same files — no rewriting needed.
   Asserted rather than assumed, because a sheet moving into a subdirectory
   would break every asset reference in it silently. */
/* The layer statement has to be the first thing in the file: a layer's
   position in the cascade is fixed the first time it is named, so declaring
   them all up front makes the order independent of the concatenation.

   Each sheet is then wrapped in the layer crnl-loader.js would have imported
   it into, so the bundle and the local path produce the same cascade. They
   are read from the same place for that reason — a hand-kept second copy
   would differ only in production, which is the worst place to find out. */
const parts = [
  '/* GENERATED by scripts/build-css-bundle.mjs — do not edit.\n' +
  '   Source of truth is the individual stylesheets, in crnl-loader.js order.\n' +
  `   ${sheets.length} stylesheets in ${order.length} cascade layers, concatenated for delivery. */\n`,
  `@layer ${order.join(', ')};\n`,
]

for (const name of sheets) {
  if (name.includes('/')) {
    console.error(`build-css-bundle: ${name} is not directly in css/ — relative url() references would break`)
    process.exit(1)
  }
  const layer = layerFor(name)
  parts.push(`\n/* ==== ${name} ${'='.repeat(Math.max(0, 52 - name.length))} ${layer} */\n`)
  parts.push(`@layer ${layer} {\n`)
  parts.push(readFileSync(join(CSS, name), 'utf8'))
  parts.push(`\n}\n`)
}

const bundle = parts.join('')
writeFileSync(OUT, bundle)

const raw = Buffer.byteLength(bundle)
const gz = gzipSync(bundle, { level: 9 }).length
console.log(
  `Generated crnl.css — ${sheets.length} stylesheets in ${order.length} layers, ` +
  `${(raw / 1024).toFixed(0)}KB (${(gz / 1024).toFixed(0)}KB gzip)`)
